package com.rodentcontrol.customer;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.Executors;
public class IncidentsActivity extends AppCompatActivity{protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detail);TextView v=findViewById(R.id.detail);Executors.newSingleThreadExecutor().execute(()->{try{org.json.JSONArray a=Api.incidents(this).getJSONArray("incidents");StringBuilder s=new StringBuilder("Sự cố\n\n");for(int i=0;i<a.length();i++){org.json.JSONObject r=a.getJSONObject(i);s.append(r.optString("created_at")).append(" | ").append(r.optString("site_name")).append(" | ").append(r.optString("incident_type")).append(" | ").append(r.optString("severity")).append(" | ").append(r.optString("status")).append("\n");}runOnUiThread(()->v.setText(s.toString()));}catch(Exception e){runOnUiThread(()->v.setText(e.getMessage()));}});}}
